let cloud=null,route=location.hash.slice(1)||'home',cashTab='inventory',box=1,memoFilter='active',memoScope='local',cardFilter='active',searches={},scrolls={},modalDirty=false,modalDraft='',lastActive=Date.now(),webBusy=false,weather=read('pos-weather',null),weatherError='',weatherLoading=false,stopState=read('pos-stopwatch',{start:0,elapsed:0,laps:[]}),wake=null;
