function night(){const t=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Hong_Kong',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());return U.darkStart>U.lightStart?(t>=U.darkStart||t<U.lightStart):(t>=U.darkStart&&t<U.lightStart);}
function libraryOpen(){if(U.library==='page')return go('library');showSheet('程式庫',`<input id="app-filter" class="filter-input" placeholder="搜尋 App" aria-label="搜尋 App">${tools()}<div class="tools-grid">${APPS.slice(3).map(([r,i,n])=>`<button class="tool-card" data-tool="${i}" data-route="${r}"><span class="tool-icon">${appIcon(i)}</span><strong>${n}</strong></button>`).join('')}</div><div class="button-row">${button('settings','設定','settings')}${button('sync','同步與配對','sync')}</div>`);$('#sheet').classList.add('library-sheet');$('#app-filter').oninput=e=>{$$('.tool-card',$('#sheet')).forEach(el=>el.hidden=!el.textContent.includes(e.target.value));};}
function uiSelect(k,label,opts){return `<label class="setting-row"><span>${label}</span><select data-ui="${k}">${opts.map(([v,n])=>`<option value="${v}" ${String(U[k])===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`;}
function systemSettings(){return `<section class="panel"><h2>私人系統</h2>${uiSelect('theme','外觀模式',[['light','淺色'],['dark','深色'],['schedule','按時間'],['system','跟隨裝置']])}<div class="settings-grid"><label class="field">日間開始<input type="text" inputmode="text" placeholder="HH:MM" maxlength="5" data-ui="lightStart" value="${U.lightStart}"></label><label class="field">夜間開始<input type="text" inputmode="text" placeholder="HH:MM" maxlength="5" data-ui="darkStart" value="${U.darkStart}"></label></div>${uiSelect('library','程式庫開啟方式',[['sheet','浮動面板'],['page','獨立全頁']])}${uiSelect('animation','動畫風格',[['lively','精緻流動'],['playful','彈性互動'],['off','減少動畫']])}${uiSelect('idle','閒置返回工具',[[0,'不自動返回'],[1,'1 分鐘'],[3,'3 分鐘'],[5,'5 分鐘']])}${uiSelect('sound','新備忘提示聲',[['true','開啟'],['false','關閉']])}${uiSelect('private','主頁備忘內容',[['false','顯示標題'],['true','只顯示數量']])}<label class="field">夜深提醒時間<input type="text" inputmode="text" placeholder="HH:MM" maxlength="5" data-ui="reminder" value="${U.reminder}"></label><p class="draft-hint">外觀、已讀及置頂標記只影響此裝置。聲音需先與網站互動；提醒不會打斷輸入。</p>${button('sound-test','試聽提示聲','bell','secondary')}</section>`;}
let audioContext=null;
function sound(){if(U.sound!==true&&U.sound!=='true')return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state!=='running')return;const t=audioContext.currentTime;[660,880].forEach((hz,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=hz;o.connect(g);g.connect(audioContext.destination);g.gain.setValueAtTime(0,t+i*.1);g.gain.linearRampToValueAtTime(.065,t+i*.1+.015);g.gain.exponentialRampToValueAtTime(.001,t+i*.1+.26);o.start(t+i*.1);o.stop(t+i*.1+.3);});}catch{}}
async function completeMemo(m,scope){if(!m)return;const wasDone=!!m.done;const previous=memoScope;memoScope=scope;try{await changeMemo(m,{done:!m.done});undoMemo={id:m.id,scope,done:wasDone};render();toast(wasDone?'已恢復未完成':'已完成備忘');$('#toast').insertAdjacentHTML('beforeend','<button data-act="undo-memo" class="text-button">復原</button>');}finally{memoScope=previous;}}
function overlayDrafts(state){state.drafts??={};for(const k of Object.keys(localStorage).filter(k=>k.startsWith('pos-draft:'))){try{const v=JSON.parse(localStorage.getItem(k));if(v!==null)state.drafts[k.slice(10)]=v;else delete state.drafts[k.slice(10)];}catch{}}return state;}
