function locked(fn){return navigator.locks?navigator.locks.request('personalos-write',fn):Promise.resolve().then(fn);}
async function update(fn,web=false){if(broken)throw Error('資料讀取異常，已停止寫入；請先匯出原始資料');return locked(()=>{const raw=localStorage.getItem(KEY),next=raw?validateState(JSON.parse(raw)):emptyState();overlayDrafts(next);const previousDrafts=JSON.stringify(next.drafts);fn(next);if(JSON.stringify(next.drafts)!==previousDrafts){for(const k of Object.keys(S.drafts||{}))if(!(k in next.drafts))localStorage.setItem('pos-draft:'+k,'null');}validateState(next);localStorage.setItem(KEY,JSON.stringify(next));S=next;if(web){localStorage.setItem('pos-web-dirty','1');queueMicrotask(syncWeb);}return next;});}
