function title(k,h,p='',action=''){k=({cash:'每一筆，都有記錄',memos:'留低想法，放輕心事',cards:'每份記憶，都有位置',library:'你嘅私人 App 中心',settings:'調整成你鍾意嘅樣',clock:'此刻，剛剛好',stopwatch:'掌握自己嘅節奏'})[route]||'私人生活空間';return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${esc(h)}</h1><p>${esc(p)}</p></div>${action}</div>`;}
