function applySettings(){document.documentElement.dataset.motion=S.settings.motion&&U.animation!=='off'?'on':'off';document.documentElement.dataset.large=S.settings.font>1.1?'true':'false';document.documentElement.dataset.contrast=S.settings.contrast?'high':'normal';document.documentElement.dataset.theme=U.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):U.theme==='schedule'?(night()?'dark':'light'):U.theme;document.documentElement.dataset.playful=U.animation==='playful';document.documentElement.style.zoom=String(S.settings.font||1);}
