function render(){const y=scrollY;const feed=$('.memo-feed');if(feed)U.feedScroll=feed.scrollTop;stashNav();applySettings();document.body.dataset.page=route;if(route==='display'){renderDisplay();return;}const nav=navs.find(x=>x[0]===route),label=nav?.[2]||({settings:'設定',clock:'時鐘',stopwatch:'秒錶'}[route]||'首頁');$('#app').innerHTML=`<div class="scroll-progress"></div><div class="shell"><aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div><strong>PersonalOS</strong><small>私人生活空間</small></div></div><nav class="nav" aria-label="主要導覽">${navs.map(([r,i,n],j)=>`<button data-route="${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${n}</span><span class="nav-num">0${j+1}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sync-line"><span class="dot"></span><span id="sidebar-status">${navigator.onLine?'本機資料已就緒':'離線 · 本機資料保留'}</span></div><p>一個屬於你嘅生活空間</p>${button('settings','偏好設定','settings','text-button')}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="text-button" data-route="home">${icon('home')}返回工具</button><span class="route-separator" aria-hidden="true">›</span><strong aria-current="page">${locationLabel()}</strong></div><div class="top-actions"><button class="search-launch" data-act="search" aria-label="搜尋工具及紀錄">${icon('search')}<span>搜尋空間</span><kbd>⌘ K</kbd></button>${button('sync','', 'sync','icon-btn','aria-label="同步與配對"')}${button('settings','','settings','icon-btn','aria-label="設定"')}</div></header><main id="main" tabindex="-1">${broken?'<div class="status-banner">本機資料未能讀取。已停止寫入，原始內容保留。請到設定匯出原始資料。</div>':''}${outcome?.route===route?`<div class="operation-result" role="status">${icon('check')}<div><strong>${esc(outcome.title)}</strong><p>${esc(outcome.detail)}</p></div></div>`:''}${['cash','cards'].includes(route)?'<div class="storage-status" role="status" data-storage-status></div>':''}${page()}</main><footer class="footer-note"><span>PERSONALOS · DESIGNED FOR EVERYDAY LIFE</span><span>香港 · 私人生活中控台</span></footer></div></div>`;tick();bindPage();scrollTo(0,y);}
function page(){switch(route){case'cash':return cashPage();case'memos':return memoPage();case'cards':return cardsPage();case'library':return libraryPage();case'settings':return settingsPage();case'clock':return title('TIME & SPACE','香港時間','慢一點，留返空間畀生活。')+`<div class="panel"><div class="clock" style="text-align:center" data-clock>${clock()}</div><p style="text-align:center;color:var(--muted)">${date()}</p><div class="button-row" style="justify-content:center">${button('display','進入展示模式','display','primary')}</div></div>`;case'stopwatch':return libraryPage();default:return libraryPage();}}
function timePanel(){return `<section class="time-panel"><div class="time-meta"><span>HONG KONG</span><span class="pill"><span class="dot ok"></span>HKT · UTC+8</span></div><div class="clock" data-clock>${clock()}</div><div class="time-footer"><span>${date()}</span><button data-act="display">進入展示 ${icon('arrow')}</button></div></section>`;}
function weatherPanel(){if(!S.settings.weather)return `<section class="weather-panel"><div class="eyebrow">A LITTLE BREATHING ROOM</div><h2 style="font-weight:350">留一點空間，<br>畀生活。</h2>${button('settings','天氣內容已隱藏','settings','text-button')}</section>`;const d=weather?.current,temps=d?.temperature?.data||[],temp=temps.find(x=>x.place==='香港天文台')?.value??temps[0]?.value,humid=d?.humidity?.data?.[0]?.value;const stale=!weather||Date.now()-weather.at>600000||Date.now()-Date.parse(d?.updateTime)>7200000;const warn=activeWarnings(weather?.warnings),symbol=weatherSymbol(d?.icon?.[0]);return `<section class="weather-panel"><div class="weather-head"><span>香港天氣</span><button class="text-button" data-act="weather" aria-label="更新天氣">${icon('sync')}</button></div><div class="weather-main"><div class="temperature">${temp??'—'}<small>°</small></div><div class="weather-orb">${symbol?`<img class="hko-weather-icon" src="${symbol.src}" alt="${esc(symbol.name)}" width="64" height="64">`:`<span aria-label="天氣狀況未有資料">—</span>`}</div></div><div class="weather-condition">${symbol?esc(symbol.name):'天氣狀況未有資料'}</div><div class="weather-warnings" aria-label="天氣警告">${warn.map(w=>`<div class="weather-warning">${w.src?`<img src="${w.src}" alt="${esc(w.name||w.code)}" width="52" height="52">`:icon('info')}<span>${esc(w.name||w.code)}<small>${stale?'快取警告 · 待更新確認':'生效中'}</small></span></div>`).join('')}</div><div class="weather-desc">${warn.length?'':weather?.warnings?'暫無生效天氣警告':'天氣警告尚未取得'}${stale&&weather?' · 快取可能過期':''}</div><div class="weather-bottom"><span>濕度 ${humid??'—'}%</span><span>${weatherLoading?'更新中…':weatherError?'更新失敗 · '+(d?'資料 '+fmt(Date.parse(d.updateTime)):'尚未取得資料'):d?'資料 '+fmt(Date.parse(d.updateTime)):'尚未取得資料'}</span></div>${S.settings.forecast&&weather?.forecast?.weatherForecast?`<div class="forecast">${weather.forecast.weatherForecast.slice(0,3).map(f=>`<div><span>${esc(f.week)}</span><strong>${f.forecastMintemp?.value}–${f.forecastMaxtemp?.value}°</strong></div>`).join('')}</div>`:''}</section>`;}
function tools(){return `<div class="tools-grid">${[['cash','cash','現金管理','收款、支出、轉移及盤點'],['memos','memo','備忘錄','新增待辦、編輯及完成事項'],['cards','sd','SD 卡紀錄','管理容量、用途及備份記錄']].map(([r,i,h,p])=>`<button class="tool-card" data-tool="${i}" data-route="${r}"><span class="tool-icon">${appIcon(i)}</span><span><strong>${h}</strong><small>${p}</small></span>${icon('arrow')}</button>`).join('')}</div>`;}
function homePage(){const draft=S.drafts['quick-note']||'',recent=S.recent.slice(0,3);return title('YOUR EVERYDAY, IN HARMONY',S.settings.name||'我的空間','安排好瑣事，留多一點時間畀生活。',`<span class="pill">${icon('home')} HOME CONSOLE</span>`)+`<div class="hero-grid">${timePanel()}${weatherPanel()}</div><div class="section-head"><h2>生活工具</h2><small>ESSENTIALS</small></div>${tools()}<div class="lower-grid"><section><div class="section-head"><h2>隨手記低</h2><button class="text-button" data-route="memos">所有備忘 ${icon('arrow')}</button></div><form id="quick-form"><div class="quick-note">${icon('edit')}<input name="note" aria-label="新增備忘" placeholder="有乜想記低？" value="${esc(draft)}" autocomplete="off"><button aria-label="保存備忘">${icon('arrow')}</button></div><p class="draft-hint" id="quick-hint">${draft?'草稿已保留 · 尚未保存正式備忘':'直接輸入，本機保存；雲端備忘請進入備忘工具。'}</p></form>${S.memos.filter(m=>!m.done&&!m.deleted).slice(0,2).map(m=>`<button class="recent-row" data-act="edit-memo" data-id="${esc(m.id)}">${icon('memo')}<span>${esc(m.title)}</span>${icon('arrow')}</button>`).join('')}</section><section><div class="section-head"><h2>最近使用</h2><small>RECENT</small></div>${recent.length?recent.map(r=>{const n=navs.find(x=>x[0]===r)||[r,r,r==='stopwatch'?'秒錶':'時鐘'];return `<button class="recent-row" data-route="${r}">${icon(n[1])}<span>${n[2]}</span>${icon('arrow')}</button>`;}).join(''):'<p class="home-empty">由一個工具開始，<br>常用入口會留喺呢度。</p>'}</section></div>`;}
function cashPage(){const es=entries(S.revisions),snap=replay(es),q=snap.q[box],needle=(searches.cash||'').toLowerCase();return title('CASH, CONSIDERED','現金管理','查看庫存、記錄現金流向，修訂亦有歷史可查。',button('cash-history','交易歷史','history','secondary'))+`<section class="panel"><div class="balance-hero"><div><div class="balance-label">現金總庫存 · HKD</div><div class="balance">${money(snap.total)}</div><span class="pill">${S.revisions.length} 筆歷史修訂 · ${localStorage.getItem('pos-web-sync')==='1'?(localStorage.getItem('pos-web-dirty')==='1'?'共用待確認':'共用狀態見同步頁'):'本機紀錄'}</span></div><div class="vault-breakdown">${BOXES.map((b,i)=>`<div><span style="color:var(--muted)">${b}</span><span>${money(amount(snap.q[i]))}</span></div>`).join('')}</div></div><div class="task-heading"><h2>你想記錄乜嘢？</h2><p>先揀操作，再填紙幣張數或硬幣枚數。</p></div><div class="cash-actions task-actions">${[['DEPOSIT','收到現金','今次收到幾多 · 預設放入臨時箱','down'],['WITHDRAW','提取／支出','由指定保管箱取出現金','up'],['TRANSFER','整理／轉移','搬去另一個箱 · 唔計收入或支出','transfer'],['AUDIT','實物盤點','填箱內實際總數 · 唔係今次增減','check']].map(([t,n,d,i])=>`<button class="task-action ${t==='DEPOSIT'?'featured':''}" data-act="cash-new" data-type="${t}"><span class="task-icon">${icon(i)}</span><span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div></section>${!es.length?'<div class="notice">網站尚未有現金紀錄。你可以先匯入舊版完整資料，或者首次記錄時建立零期初庫存；唔會讀取或清除 APK 資料。</div>':''}<div class="toolbar"><div class="segmented">${['inventory','history'].map((v,i)=>`<button data-act="cash-tab" data-value="${v}" class="${cashTab===v?'selected':''}">${i?'交易紀錄':'庫存明細'}</button>`).join('')}</div>${cashTab==='inventory'?`<div class="segmented">${BOXES.map((b,i)=>`<button data-act="box" data-value="${i}" class="${box===i?'selected':''}">${b}</button>`).join('')}</div>`:`<input class="filter-input" data-search="cash" aria-label="搜尋交易" placeholder="搜尋類型、保管箱或交易 ID" value="${esc(searches.cash||'')}">`}</div>${cashTab==='inventory'?`<div class="view-context"><strong>正在查看：${BOXES[box]}</strong><span>下方係現有庫存；記錄新操作請用上方入口。</span></div><div class="section-head"><h2>紙幣</h2><small>BANKNOTES</small></div><div class="inventory">${q.slice(0,6).map((n,i)=>denom(n,i)).join('')}</div><div class="section-head"><h2>硬幣</h2><small>COINS</small></div><div class="inventory">${q.slice(6).map((n,i)=>denom(n,i+6)).join('')}</div>`:es.filter(e=>(TYPES[e.type]+BOXES[e.from]+e.id).toLowerCase().includes(needle)).reverse().map(e=>`<button class="record ${e.voided?'voided':''}" data-act="transaction" data-id="${e.id}"><span class="record-icon">${icon(e.type==='DEPOSIT'?'down':e.type==='WITHDRAW'?'up':e.type==='TRANSFER'?'transfer':'history')}</span><span class="record-content"><strong>${TYPES[e.type]}${e.voided?' · 已作廢':''}</strong><small>${BOXES[e.from]}${e.type==='TRANSFER'?' → '+BOXES[e.to]:''} · ${fmt(e.timestamp)}</small></span><span class="record-amount">${money(amount(e.counts))}</span>${icon('chevron')}</button>`).join('')||empty('cash',needle?'搵唔到相關交易':'未有交易紀錄',needle?'試吓其他關鍵字。':'收到現金後，由上方開始記錄。')}`;}
function currencyBadge(i){return `<span class="currency-badge ${i<6?'note':'coin'} currency-${i}" aria-label="港幣 ${LABELS[i]} 元${i<6?'紙幣':'硬幣'}"><span class="currency-unit">HK$</span><b>${LABELS[i]}</b><span class="currency-kind">${i<6?'紙幣':'硬幣'}</span></span>`;}
function denom(n,i){return `<article class="denom"><div class="denom-top">${currencyBadge(i)}</div><div class="quantity">${n.toLocaleString()}<small>${i<6?'張':'枚'}</small></div><small>${money(n*CENTS[i])}</small></article>`;}
function memos(){if(memoScope!=='cloud')return S.memos;const list=clone(cloud?.state.docs||[]);for(const op of cloud?.state.queue||[]){if(!op.path.startsWith(cloud.path()+'/'))continue;const id=op.path.split('/').pop(),old=list.find(x=>x.id===id),m={...(old||{}),id,title:op.title,note:op.note,done:op.done,deleted:op.deleted,pending:true,conflict:op.conflict,updated:op.queuedAt};if(old)Object.assign(old,m);else list.unshift(m);}return list;}
function memoPage(){const list=memos().sort((a,b)=>Number(!!meta[memoKey(b)]?.pin)-Number(!!meta[memoKey(a)]?.pin)||(b.created||b.updatedAt?.seconds*1000||b.updated||0)-(a.created||a.updatedAt?.seconds*1000||a.updated||0)),needle=(searches.memos||'').toLowerCase(),shown=list.filter(m=>(memoFilter==='deleted'?m.deleted:!m.deleted&&(memoFilter==='done'?m.done:!m.done))&&(m.title+' '+m.note).toLowerCase().includes(needle));const dk='memo-compose-'+memoScope;return title('LESS ON YOUR MIND','備忘錄','上方直接新增；點內容編輯，勾選先代表完成。')+`<div class="toolbar"><div class="segmented"><button data-act="memo-scope" data-value="local" class="${memoScope==='local'?'selected':''}">本機備忘</button><button data-act="memo-scope" data-value="cloud" class="${memoScope==='cloud'?'selected':''}">雲端備忘</button></div>${button('sync','同步與配對','sync','text-button')}</div>${memoScope==='cloud'?`<div class="status-banner">${esc(cloud?.state.status||'未連接原 Firebase')}${cloud?.state.space?' · 共用空間':' · 個人空間'}</div>`:''}<form id="memo-form" class="memo-composer"><label class="composer-label" for="memo-compose-text">新增備忘 <small>${memoScope==='cloud'?'加入雲端待送佇列':'儲存喺此裝置'}</small></label><textarea id="memo-compose-text" name="text" aria-label="新增備忘內容" placeholder="有乜想記低？直接喺呢度輸入…">${esc(S.drafts[dk]||'')}</textarea><div class="composer-footer"><span id="memo-draft-hint">${S.drafts[dk]?'草稿已保留 · 尚未送出':'第一行係標題，其餘係內容'}</span><button class="primary" ${memoScope==='cloud'&&!cloud?.state.uid?'disabled':''}>${icon('plus')}保存備忘</button></div></form><div class="toolbar"><div class="segmented">${[['active','未完成'],['done','已完成'],['deleted','已刪除']].map(([v,n])=>`<button data-act="memo-filter" data-value="${v}" class="${memoFilter===v?'selected':''}">${n}</button>`).join('')}</div><label class="list-search">搜尋現有備忘<input class="filter-input" data-search="memos" aria-label="搜尋現有備忘" placeholder="輸入關鍵字篩選列表" value="${esc(searches.memos||'')}"></label></div><div>${shown.length?shown.map(m=>`<article class="memo-row ${m.done?'completed':''}"><button class="check ${m.done?'done':''}" data-act="toggle-memo" data-id="${m.id}" aria-label="${m.done?'設為未完成':'標記完成'}：${esc(m.title)}" ${m.deleted?'disabled':''}><span>${m.done?icon('check'):''}</span></button><button class="memo-body" data-act="edit-memo" data-id="${m.id}"><strong>${esc(m.title)}</strong>${m.note?`<p>${esc(m.note)}</p>`:''}<small>${fmt(m.updatedAt||m.updated)}${m.deleted?' · 已刪除':''}${m.pending?' · 待同步':''}${m.conflict?' · 衝突已保留':''}</small></button><button class="text-button memo-manage" data-act="${m.deleted?'restore-memo':'delete-memo'}" data-id="${m.id}" aria-label="${m.deleted?'還原':'刪除'}備忘">${icon(m.deleted?'history':'trash')}<span>${m.deleted?'還原':'刪除'}</span></button></article>`).join(''):empty('memo',needle?'搜尋無結果':memoFilter==='deleted'?'未有已刪除備忘':memoFilter==='done'?'未有已完成備忘':'暫時冇未完成事項',needle?'試吓用另一個關鍵字。':'需要記住嘅事，就交畀呢度。')}</div>`;}
function cardsPage(){const needle=(searches.cards||'').toLowerCase(),list=S.cards.filter(c=>(cardFilter==='deleted'?c.deleted:!c.deleted&&(cardFilter==='archived'?c.archived:!c.archived))&&(c.name+' '+c.purpose+' '+c.notes+' '+c.status).toLowerCase().includes(needle));return title('A PLACE FOR EVERY MEMORY','SD 卡紀錄','記錄每張卡嘅容量、用途及手動備份狀態。',button('new-card','新增紀錄','plus','primary'))+`<div class="toolbar"><div class="segmented">${[['active','使用中'],['archived','已封存'],['deleted','已刪除']].map(([v,n])=>`<button data-act="card-filter" data-value="${v}" class="${cardFilter===v?'selected':''}">${n}</button>`).join('')}</div><input class="filter-input" data-search="cards" aria-label="搜尋 SD 卡" placeholder="搜尋名稱、用途或狀態" value="${esc(searches.cards||'')}"></div>${list.length?`<div class="sd-grid">${list.sort((a,b)=>b.updated-a.updated).map(c=>`<article class="sd-item"><button class="sd-card" data-act="card" data-id="${c.id}"><div class="sd-top">${icon('sd')}<span class="pill">${esc(c.status||'待拍')}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.purpose||'尚未填寫用途')}</p><footer><span>${esc(c.capacity||'未填容量')}</span><span>${fmt(c.updated)}</span></footer></button><div class="sd-actions">${button('edit-card','編輯','edit','text-button',`data-id="${c.id}"`)}${button('card','查看／更多','more','text-button',`data-id="${c.id}"`)}</div></article>`).join('')}</div>`:empty('sd',needle?'搜尋無結果':cardFilter==='active'?'每張卡，都有自己的位置':'呢度暫時未有紀錄',needle?'試吓其他名稱、用途或狀態。':'記低名稱、容量與用途，下次搵卡更輕鬆。',button('new-card','新增 SD 卡','plus','primary'))}<div class="notice">容量及備份狀態係手動記錄，唔代表已讀取實體卡或完成備份。刪除紀錄唔會刪除卡內檔案。</div>`;}
const QUICK_ACTIONS=[['WITHDRAW','記錄支出','cash'],['DEPOSIT','收到現金','cash'],['memo','寫備忘','memo'],['TRANSFER','整理現金','cash']];
function conveniencePanel(){const draft=S.drafts['cash-new'];return `<section class="convenience"><div class="section-head"><h2>即刻記低</h2><small>保存前會核對</small></div><div class="quick-actions">${QUICK_ACTIONS.map(([v,n,i])=>button('quick-start',n,i,'shortcut',`data-value="${v}"`)).join('')}</div>${draft?.entry?`<button class="resume-draft" data-act="resume-cash">${icon('edit')}<span><strong>繼續${esc(TYPES[draft.entry.type]||'現金')}草稿</strong><small>尚未入帳 · 返回上次輸入</small></span>${icon('arrow')}</button>`:''}${S.drafts['memo-quick-sheet']?button('quick-start','繼續備忘草稿','memo','resume-draft','data-value="memo"'):''}${S.drafts['card-new']?button('resume-card','繼續 SD 卡草稿','cards','resume-draft'):''}</section>`;}
function libraryPage(){const recent=S.recent.filter(r=>['cash','memos','cards','clock'].includes(r)).slice(0,3);return `<div class="tool-hub">`+title('PERSONALOS · 工具模式','我的工具','入程式處理紀錄，或用下方捷徑直接開始。',button('display','返回展示模式','display','secondary'))+`<section class="hub-apps" aria-label="主要程式"><div class="section-head"><h2>主要程式</h2><small>完整管理與紀錄</small></div>${tools()}</section><div class="hub-secondary">${conveniencePanel()}<section class="hub-recent"><div class="section-head"><h2>最近使用</h2></div>${recent.length?recent.map(r=>{const a=APPS.find(x=>x[0]===r);return `<button class="recent-row" data-route="${r}">${icon(a[1])}<span>${a[2]}</span>${icon('arrow')}</button>`;}).join(''):'<p class="home-empty">使用過嘅程式會留喺呢度。</p>'}<button class="recent-row" data-route="clock">${icon('clock')}<span>香港時鐘</span>${icon('arrow')}</button></section></div><section class="hub-management"><div><h2>空間管理</h2><p>外觀、配對與資料備份</p></div><div class="button-row">${button('settings','設定','settings')}${button('sync','同步與配對','sync')}${button('backup','完整備份','download')}${button('import','匯入資料','upload')}</div></section></div>`;}

function toggleSetting(key,name,desc){return `<label class="setting-row"><span>${name}<small>${desc}</small></span><span class="switch-wrap"><input type="checkbox" class="switch" data-setting="${key}" ${S.settings[key]?'checked':''}></span></label>`;}
function settingsPage(){return title('MAKE IT YOURS','設定','調整到最適合你嘅節奏。')+systemSettings()+`<div class="settings-grid"><section class="panel"><h2>外觀與閱讀</h2><label class="field">空間名稱<input class="filter-input" data-text-setting="name" value="${esc(S.settings.name)}" maxlength="40"></label>${toggleSetting('motion','自然動態','系統減少動態設定仍會優先生效')}${toggleSetting('contrast','提高對比','加強輔助文字及邊界辨識')}<label class="setting-row"><span>文字大小</span><select class="filter-input" data-setting="font">${[[1,'標準'],[1.15,'較大'],[1.3,'大字']].map(([v,n])=>`<option value="${v}" ${S.settings.font===v?'selected':''}>${n}</option>`).join('')}</select></label></section><section class="panel"><h2>展示與天氣</h2>${toggleSetting('weather','顯示天氣','香港天文台資料及更新時間')}${toggleSetting('forecast','顯示預報','未來三日溫度概覽')}</section><section class="panel"><h2>同步與通知</h2><label class="field">裝置自訂名稱<input class="filter-input" data-text-setting="deviceName" maxlength="60" value="${esc(S.settings.deviceName)}"></label><p style="color:var(--muted);font-size:12px">${esc(cloud?.state.status||'未連接原 Firebase 專案')}</p><div class="button-row">${button('sync','同步與配對','sync')}${button('push','背景通知設定','bell')}</div></section><section class="panel"><h2>資料與備份</h2><p style="color:var(--muted);font-size:12px">完整備份包含交易及修訂、備忘、SD 卡、草稿及本機待送資料。匯入採合併，不清空現有內容。</p><div class="button-row">${button('backup','匯出完整備份','download')}${button('import','匯入資料','upload')}${button('raw','匯出原始儲存','download','text-button')}</div><p style="color:var(--muted);font-size:11px">${S.revisions.length} 筆修訂 · ${S.memos.length} 筆本機備忘 · ${S.cards.length} 張卡片紀錄</p></section></div>`;}
function stopwatchPage(){return title('ONE MOMENT AT A TIME','秒錶','分段計時，節奏由你掌握。')+`<div class="panel"><div class="stopwatch" id="stop-time"></div><div class="button-row" style="justify-content:center">${button('stop-toggle',stopState.start?'暫停':'開始',stopState.start?'minus':'watch','primary')}${button('stop-lap','分段','plus','secondary',stopState.start?'':'disabled')}${button('stop-reset','重設','history')}</div>${stopState.laps.map((n,i)=>`<div class="setting-row"><span>分段 ${i+1}</span><span>${stopFormat(n)}</span></div>`).reverse().join('')}</div>`;}
function stopFormat(ms){return `${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(Math.floor(ms/10)%100).padStart(2,'0')}`;}
function displayFeed(){const local=S.memos.map(m=>({...m,scope:'local'}));const prev=memoScope;memoScope='cloud';const remote=memos().map(m=>({...m,scope:'cloud'}));memoScope=prev;return [...local,...remote].filter(m=>!m.deleted&&!m.done).sort((a,b)=>Number(!!meta[memoKey(b,b.scope)]?.pin)-Number(!!meta[memoKey(a,a.scope)]?.pin)||(b.created||b.createdAt?.seconds*1000||b.updated||b.updatedAt?.seconds*1000||0)-(a.created||a.createdAt?.seconds*1000||a.updated||a.updatedAt?.seconds*1000||0));}
function renderDisplay(){const notes=displayFeed();$('#app').innerHTML=`<main id="main" tabindex="-1" class="ambient-home ${notes.length?'has-notes':''}"><header class="ambient-header"><div><strong>Personal<span>OS</span></strong><small>展示模式 · 香港</small></div><button class="ambient-enter" data-route="home">使用工具 ${icon('arrow')}</button></header>${broken?'<div class="status-banner">資料未能讀取，已停止寫入。請先匯出原始資料。</div>':''}<div class="ambient-grid"><section class="ambient-clock"><div class="ambient-label">${date()}</div><div class="ambient-digits" data-clock>${clock()}</div><div class="ambient-date"><span>香港時間 · HKT</span><span class="ambient-seconds"><b data-seconds></b> 秒</span></div></section><section class="ambient-weather" aria-label="香港天氣與警告">${weatherPanel()}</section>${notes.length?`<section class="ambient-notes"><div class="section-head"><h2>待辦備忘 <span class="note-count">${notes.length}</span></h2><button class="text-button" data-route="memos">查看備忘 ${icon('arrow')}</button></div><div class="memo-feed" tabindex="0" aria-label="未完成備忘，可上下捲動">${U.private===true||U.private==='true'?`<button class="ambient-note" data-route="memos"><strong>${notes.length} 項待辦</strong><p>私隱模式 · 點擊查看內容</p></button>`:notes.map(m=>`<article class="ambient-note"><button class="ambient-note-content" data-act="display-memo" data-id="${esc(m.id)}" data-scope="${m.scope}"><small>${m.scope==='cloud'?'共用備忘':'本機備忘'}${m.pending?' · 待同步':''}</small><strong>${esc(m.title)}</strong>${m.note?`<p>${esc(m.note)}</p>`:''}</button><button class="check" data-act="home-complete" data-id="${esc(m.id)}" data-scope="${m.scope}" aria-label="完成：${esc(m.title)}"><span></span></button></article>`).join('')}</div></section>`:''}</div><footer class="ambient-footer"><span>私人生活空間</span><span>${navigator.onLine?'香港時間 · HKT':'離線 · 本機內容保留'}</span></footer><div id="night-reminder" role="status"></div></main>`;const feed=$('.memo-feed');if(feed){feed.scrollTop=U.feedScroll||0;feed.onscroll=e=>{U.feedScroll=e.target.scrollTop;lastActive=Date.now();saveUI();};}tick();requestWake();}
function quickMemo(){const key='memo-quick-sheet',scope=cloud?.state.uid?'cloud':'local';showSheet('隨手記低',`<p class="draft-hint">${scope==='cloud'?'沿用已連接嘅雲端備忘空間':'保存於本機備忘'} · 未送出內容會保留草稿</p><label class="field">新增備忘<textarea id="quick-memo-text" placeholder="第一行係標題，其餘係內容…">${esc(S.drafts[key]||'')}</textarea></label>`,`<button class="primary" id="quick-memo-save">${icon('arrow')}保存備忘</button>`);const input=$('#quick-memo-text');input.oninput=()=>{modalDirty=true;saveDraft(key,input.value).catch(sheetError);};$('#quick-memo-save').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;try{const [head,...body]=input.value.trim().split('\n');if(!head||head.length>200||body.join('\n').length>10000)throw Error('標題 1–200 字，內容最多 10,000 字');const m={title:head,note:body.join('\n'),done:false,deleted:false};if(scope==='cloud')cloud.enqueue(m);else await update(s=>s.memos.unshift({...m,id:uuid(),created:Date.now(),updated:Date.now()}));await update(s=>delete s.drafts[key]);sheetExit($('#sheet'));render();toast(scope==='cloud'?'已加入待送佇列':'備忘已保存於本機');}catch(e){sheetError(e);b.disabled=false;}};input.focus();}
async function requestWake(){try{if('wakeLock'in navigator&&!wake)wake=await navigator.wakeLock.request('screen');wake?.addEventListener('release',()=>wake=null);}catch{}}
function tick(){const time=clock();$$('[data-clock]').forEach(e=>{if(e.innerHTML!==time)e.innerHTML=time;});$$('[data-seconds]').forEach(e=>{const n=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Hong_Kong',second:'2-digit'}).format(new Date()).padStart(2,'0');if(e.textContent!==n)e.textContent=n;});if($('#stop-time'))$('#stop-time').textContent=stopFormat(stopState.elapsed+(stopState.start?Date.now()-stopState.start:0));}
async function go(next,record=true){stashNav();if(next==='library'&&U.library==='sheet'){libraryOpen();return;}if(next==='stopwatch')next='home';if(!['home','cash','memos','cards','library','settings','clock','stopwatch','display'].includes(next))next='home';scrolls[route]=scrollY;route=next;if(record&&location.hash!=='#'+next)history.pushState(null,'','#'+next);if(!['home','settings','display','library'].includes(next))await update(s=>{s.recent=[next,...s.recent.filter(x=>x!==next)].slice(0,8);});if(!['home','display'].includes(next)&&wake){await wake.release();wake=null;}const targetY=scrolls[next]||0;const draw=()=>{render();scrolls[next]=targetY;scrollTo(0,targetY);};await routeTransition(draw,next);}
function download(name,obj){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function showSheet(h,html,actions=''){const d=$('#sheet'),wasOpen=d.open;d.classList.toggle('library-sheet',h==='程式庫');d.classList.toggle('cash-fullscreen',html.includes('operation-steps'));modalDirty=false;modalDraft='';d.innerHTML=`<div class="sheet-head"><div class="sheet-heading"><p class="sheet-location">${route==='display'?'展示模式':'工具模式'}${!['home','display'].includes(route)?' › '+locationLabel():''} › <span id="sheet-operation">${esc(h)}</span></p><h2 id="sheet-title">${esc(h)}</h2></div>${button('close-sheet','返回'+locationLabel(),'chevron','sheet-return')}</div><div class="sheet-body">${html}<div class="error" role="alert" id="sheet-error"></div></div>${actions?`<div class="sheet-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();d.scrollTop=0;sheetEnter(d,wasOpen);enhanceSelects(d);}
async function closeSheet(){if(modalDirty)toast('輸入已保留為草稿，未保存正式紀錄');sheetExit($('#sheet'));modalDirty=false;modalDraft='';if(['home','display'].includes(route))render();}
function sheetError(e){const x=$('#sheet-error');if(x)x.textContent=e.message||e;else toast(e.message||e);}
function field(name,label,value='',type='text'){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" autocomplete="off"></label>`;}
function confirmSheet(h,p,fn){showSheet(h,`<p>${esc(p)}</p>`,button('close-sheet','返回','','secondary')+`<button class="primary" id="confirm-action">確認</button>`);$('#confirm-action').onclick=async e=>{e.currentTarget.disabled=true;try{await fn();sheetExit($('#sheet'));render();}catch(err){sheetError(err);$('#confirm-action').disabled=false;}};}
async function saveDraft(key,value){localStorage.setItem('pos-draft:'+key,JSON.stringify(value));S.drafts[key]=clone(value);}
function bindPage(){$$('[data-ui]').forEach(e=>e.onchange=()=>{if(['lightStart','darkStart','reminder'].includes(e.dataset.ui)&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.value)){e.value=U[e.dataset.ui];toast('時間請填 00:00 至 23:59');return;}U[e.dataset.ui]=e.value;saveUI();render();});$$('.segmented button').forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('selected')));const quick=$('#quick-form');if(quick){quick.note.oninput=()=>{saveDraft('quick-note',quick.note.value).catch(toast);$('#quick-hint').textContent='草稿已保留 · 尚未保存正式備忘';};quick.onsubmit=async e=>{e.preventDefault();try{const text=quick.note.value.trim();if(!text)throw Error('請先輸入內容');if(text.length>200)throw Error('標題最多 200 字，長內容請到備忘錄輸入');await update(s=>{s.memos.unshift({id:uuid(),title:text,note:'',done:false,deleted:false,updated:Date.now()});delete s.drafts['quick-note'];});render();toast('備忘已保存於本機');}catch(e){toast(e.message);}};}
const form=$('#memo-form');if(form){const key='memo-compose-'+memoScope;form.text.oninput=()=>{saveDraft(key,form.text.value).catch(e=>toast(e.message));$('#memo-draft-hint').textContent='草稿已保留 · 尚未送出';};form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const [head,...body]=form.text.value.trim().split('\n'),m={title:head,note:body.join('\n'),done:false,deleted:false};if(!head||head.length>200||m.note.length>10000)throw Error('標題 1–200 字，內容最多 10,000 字');if(memoScope==='cloud')cloud.enqueue(m);else await update(s=>s.memos.unshift({...m,id:uuid(),created:Date.now(),updated:Date.now()}));await update(s=>delete s.drafts[key]);render();toast(memoScope==='cloud'?'已加入待送佇列':'備忘已保存');}catch(e){toast(e.message);b.disabled=false;}};}
$$('[data-search]').forEach(e=>e.oninput=()=>{const pos=e.selectionStart;searches[e.dataset.search]=e.value;render();const next=$(`[data-search="${e.dataset.search}"]`);next?.focus();next?.setSelectionRange(pos,pos);});
$$('[data-setting]').forEach(e=>e.onchange=async()=>{await update(s=>s.settings[e.dataset.setting]=e.type==='checkbox'?e.checked:Number(e.value));render();});
$$('[data-text-setting]').forEach(e=>e.onchange=async()=>{await update(s=>s.settings[e.dataset.textSetting]=e.value.trim()||'我的空間');if(e.dataset.textSetting==='deviceName'){localStorage.setItem('pos-device-name',e.value.trim()||'此瀏覽器');cloud?.heartbeat();}toast('設定已保存');});}
let cashEdit=null,cashDraftKey='',cashBaseRevision=0;
function cashEditor(type='DEPOSIT',id=null){const saved=id?entries(S.revisions).find(e=>e.id===id):null;cashDraftKey='cash-'+(id||'new');if(!id&&S.drafts[cashDraftKey]?.entry?.type!==type&&S.drafts[cashDraftKey]?.entry){const old=S.drafts[cashDraftKey];localStorage.setItem('pos-draft:cash-saved-'+old.entry.type,JSON.stringify(old));S.drafts['cash-saved-'+old.entry.type]=old;const restored=S.drafts['cash-saved-'+type]||null;localStorage.setItem('pos-draft:'+cashDraftKey,JSON.stringify(restored));if(restored)S.drafts[cashDraftKey]=restored;else delete S.drafts[cashDraftKey];}cashBaseRevision=Math.max(0,...S.revisions.filter(r=>r.id===id).map(r=>r.revision));const draft=S.drafts[cashDraftKey];cashEdit=draft?.entry?clone(draft.entry):saved?clone(saved):{id:uuid(),type,from:type==='DEPOSIT'?1:box,to:box===0?1:0,counts:zero(),timestamp:Date.now(),voided:false};if(!id&&!draft){cashEdit.type=type;if(type==='AUDIT')cashEdit.counts=Array(13).fill('');}showSheet(saved?'修訂交易':TYPES[cashEdit.type],`${operationSteps(0)}<div id="cash-context" class="operation-context"></div><div class="notice">${saved?'修訂會追加版本，並重新驗證完整歷史。':'草稿唔等於已入帳。保存前會再次核對庫存。'}</div><fieldset class="cash-box-choice"><legend id="box-label">保管箱</legend><div class="cash-box-buttons">${BOXES.map((b,i)=>`<button type="button" data-cash-box="${i}" aria-pressed="${cashEdit.from===i}"><strong>${b}</strong><span>${cashEdit.type==='DEPOSIT'?'放入呢個箱':cashEdit.type==='AUDIT'?'盤點呢個箱':'從呢個箱提取'}</span></button>`).join('')}</div><small>切換保管箱會保留輸入數量，並重新核對可用庫存。</small></fieldset><p id="cash-description"></p><button type="button" id="cash-clear-counts" class="text-button">將今次輸入數量歸零</button>${cashEdit.type==='TRANSFER'?'<button type="button" class="secondary" id="cash-transfer-all">全部轉移可用庫存</button>':''}<div id="cash-quantities"></div>${field('reason','備註／修訂原因',draft?.reason||'')}${button('discard-cash','放棄呢份草稿','','text-button')}<p class="draft-hint">關閉會保留草稿，下次可繼續。</p>`,`<div class="cash-footer-total"><small>${cashEdit.type==='AUDIT'?'盤點實物總額':'今次合計'}</small><strong id="cash-live-total">—</strong></div>`+`<button class="primary" id="review-cash">下一步：核對數量</button>`);modalDraft=cashDraftKey;if($('#cash-transfer-all'))$('#cash-transfer-all').onclick=()=>{cashEdit.counts=limits(provisionalRows(),cashEdit);cashRows();persistCash();toast('已填入可轉移數量，請核對後保存');};if(!saved&&cashEdit.type!=='OPENING'){$('.sheet-heading').insertAdjacentHTML('beforeend',`<div class="cash-mode-switch" role="group" aria-label="現金操作">${[['DEPOSIT','收款'],['WITHDRAW','支出'],['TRANSFER','轉移'],['AUDIT','盤點']].map(([t,n])=>`<button type="button" data-cash-mode="${t}" aria-pressed="${cashEdit.type===t}">${n}</button>`).join('')}</div>`);$$('[data-cash-mode]').forEach(b=>b.onclick=async()=>{if(b.dataset.cashMode===cashEdit.type)return;await persistCash();cashEditor(b.dataset.cashMode);});}$('#cash-clear-counts').onclick=()=>{cashEdit.counts=zero();cashRows();persistCash();};$('.sheet-heading').insertAdjacentHTML('beforeend','<p class="cash-persistent-context"></p>');$$('[data-cash-box]').forEach(b=>b.onclick=()=>{cashEdit.from=Number(b.dataset.cashBox);cashEdit.to=1-cashEdit.from;cashRows();persistCash();});$('[name=reason]').oninput=persistCash;cashRows();refreshCashTotal();$('#review-cash').onclick=reviewCash;}
function provisionalRows(){if(S.revisions.length)return S.revisions;let rows=[];for(let i=0;i<2;i++)rows=saveEntry(rows,{id:'web-opening-'+i,type:'OPENING',from:i,to:i,counts:zero(),timestamp:cashEdit.timestamp-2+i,voided:false});return rows;}
function cashRows(){if(cashDraftKey==='cash-new')$('#sheet-title').textContent=TYPES[cashEdit.type];const max=limits(provisionalRows(),cashEdit);$('#sheet-operation').textContent=(cashDraftKey==='cash-new'?'':'修訂 · ')+TYPES[cashEdit.type];$('#cash-context').textContent=({DEPOSIT:'放入：',WITHDRAW:'提取來源：',TRANSFER:'轉移：',AUDIT:'盤點：',OPENING:'期初：'})[cashEdit.type]+BOXES[cashEdit.from]+(cashEdit.type==='TRANSFER'?' → '+BOXES[cashEdit.to]:'');$('#box-label').textContent=cashEdit.type==='DEPOSIT'?'放入保管箱':'來源／盤點保管箱';$('#cash-description').textContent=({DEPOSIT:'填今次收到嘅數量。',WITHDRAW:'填今次提取數量；不可超過可用庫存。',TRANSFER:'轉入'+BOXES[cashEdit.to]+'；不計新增收入或支出。',AUDIT:'填實物實際總數，唔係今次增減。',OPENING:'修改最初庫存；後續交易會一併核對。'})[cashEdit.type];$$('[data-cash-box]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.cashBox)===cashEdit.from)));const head=$('.cash-persistent-context');if(head)head.textContent=$('#cash-context').textContent;$('#cash-quantities').innerHTML=LABELS.map((v,i)=>`${i===0||i===6?`<div class="section-head"><h2>${i===0?'紙幣':'硬幣'}</h2></div>`:''}<div class="quantity-row"><div class="cash-denomination">${currencyBadge(i)}<small>${i<6?'紙幣 · 張':'硬幣 · 枚'}${max[i]!==999999?' · 最多 '+max[i]:''}</small></div><div class="cash-count-group"><div class="stepper"><button type="button" data-step="-1" data-i="${i}" aria-label="減少 ${v} ${i<6?'紙幣':'硬幣'}">−</button><input inputmode="numeric" pattern="[0-9]*" data-q="${i}" aria-label="${v} ${i<6?'紙幣張數':'硬幣枚數'}" placeholder="未點算" value="${cashEdit.counts[i]}" ${max[i]===0?'disabled':''}><button type="button" data-step="1" data-i="${i}" aria-label="增加 ${v} ${i<6?'紙幣':'硬幣'}">+</button></div><small class="cash-row-summary" data-row-summary="${i}"></small></div></div>`).join('');function refresh(i){const el=$(`[data-q="${i}"]`);let n;try{n=quantity(el.value,max[i]);el.setAttribute('aria-invalid','false');}catch{el.setAttribute('aria-invalid','true');}const bs=$$(`[data-step][data-i="${i}"]`);bs[0].disabled=n===undefined||n<=0;bs[1].disabled=(n===undefined&&el.value!=='')||n>=max[i];const detail=$(`[data-row-summary="${i}"]`);if(detail){const q=replay(entries(provisionalRows())).q[cashEdit.from][i];detail.textContent=n===undefined?(cashEdit.type==='AUDIT'&&el.value===''?'未點算 · 請填數量，冇就填 0':'數量無效或超額'):money(n*CENTS[i])+(cashEdit.type==='WITHDRAW'||cashEdit.type==='TRANSFER'?' · 可用 '+max[i]+' → 餘 '+(max[i]-n):cashEdit.type==='AUDIT'?' · 原有 '+q+' · 差額 '+(n-q>0?'+':'')+(n-q):'');}}$$('[data-q]').forEach(el=>{refresh(+el.dataset.q);el.onfocus=()=>el.select();el.oninput=()=>{cashEdit.counts[+el.dataset.q]=el.value;refresh(+el.dataset.q);persistCash();};});$$('[data-step]').forEach(b=>b.onclick=()=>{const i=+b.dataset.i,el=$(`[data-q="${i}"]`);el.value=quantity(el.value===''?'0':el.value,max[i])+(+b.dataset.step);cashEdit.counts[i]=+el.value;refresh(i);numberPop(el);persistCash();});}
function refreshCashTotal(){const el=$('#cash-live-total');if(!el||!cashEdit)return;if(cashEdit.type==='AUDIT'&&cashEdit.counts.some(n=>n==='')){el.textContent='尚有 '+cashEdit.counts.filter(n=>n==='').length+' 個面額未點算';return;}try{const max=limits(provisionalRows(),cashEdit);el.textContent=money(amount(cashEdit.counts.map((n,i)=>quantity(String(n),max[i]))));}catch{el.textContent='請修正超額或無效數量';}}
function persistCash(){refreshCashTotal();modalDirty=true;return saveDraft(cashDraftKey,{entry:cashEdit,reason:$('[name=reason]')?.value||''}).catch(sheetError);}
async function reviewCash(){try{if(cashEdit.type==='AUDIT'&&$$('[data-q]').some(el=>el.value===''))throw Error('仲有面額未點算；實際冇庫存請明確填 0。');const max=limits(provisionalRows(),cashEdit),e={...cashEdit,counts:$$('[data-q]').map((el,i)=>quantity(el.value,max[i]))},reason=$('[name=reason]').value;if(['DEPOSIT','WITHDRAW','TRANSFER'].includes(e.type)&&!e.counts.some(n=>n>0))throw Error('請至少填一個面額數量');const rows=saveEntry(provisionalRows(),e,reason),before=replay(entries(provisionalRows())),after=replay(entries(rows));await persistCash();showSheet('核對 · '+TYPES[e.type],`${operationSteps(1)}<div class="eyebrow">${TYPES[e.type]}</div><h3 style="font-size:30px;font-weight:350">${money(amount(e.counts))}</h3><p>${BOXES[e.from]}${e.type==='TRANSFER'?' → '+BOXES[e.to]:''}</p><div class="notice">${e.type==='AUDIT'?'呢個數量係實物總數。':e.type==='TRANSFER'?'只改存放位置，唔計收入或支出。':'確認後會追加正式紀錄。'}${localStorage.getItem('pos-web-sync')==='1'?' 共用資料仍須等候雲端確認。':''}</div>${BOXES.map((b,i)=>`<div class="setting-row"><span>${b}</span><span>${money(amount(before.q[i]))} → ${money(amount(after.q[i]))}</span></div>`).join('')}<p>${esc(reason)}</p>`,button('cash-back','返回修改','','secondary')+`<button class="primary" id="commit-cash">確認保存</button>`);let saved=false;$('#commit-cash').onclick=async ev=>{if(saved)return;saved=true;ev.currentTarget.disabled=true;try{await update(s=>{let base=s.revisions;if(!base.length){base=[];for(let i=0;i<2;i++)base=saveEntry(base,{id:'web-opening-'+i,type:'OPENING',from:i,to:i,counts:zero(),timestamp:e.timestamp-2+i,voided:false});}const latest=base.filter(r=>r.id===e.id).sort((a,b)=>b.revision-a.revision)[0];if(latest&&latest.revision!==cashBaseRevision&&latest.payload!==JSON.stringify(e))throw Error('此交易已被另一頁修改；草稿保留，請重新核對');s.revisions=saveEntry(base,e,reason);delete s.drafts[cashDraftKey];delete s.drafts['cash-saved-'+e.type];},true);modalDirty=false;outcome={route:'cash',title:TYPES[e.type]+'已記錄',detail:BOXES[e.from]+(e.type==='TRANSFER'?' → '+BOXES[e.to]:'')+' · '+money(amount(e.counts))+' · 已保存在本機；雲端狀態請查看同步面板'};sheetExit($('#sheet'));render();toast(TYPES[e.type]+'已記錄');}catch(err){saved=false;ev.currentTarget.disabled=false;sheetError(err);}};}catch(e){sheetError(e);}}
function transaction(id){const e=entries(S.revisions).find(e=>e.id===id);if(!e)return;showSheet(TYPES[e.type],`<div class="balance">${money(amount(e.counts))}</div><p>${BOXES[e.from]}${e.type==='TRANSFER'?' → '+BOXES[e.to]:''} · ${fmt(e.timestamp)}${e.voided?' · 已作廢':''}</p><div class="section-head"><h2>完整修訂歷史</h2></div>${S.revisions.filter(r=>r.id===id).sort((a,b)=>b.revision-a.revision).map(r=>{const p=typeof r.payload==='string'?JSON.parse(r.payload):r.payload;return `<div class="history-rev"><h3>版本 ${r.revision}${p.voided?' · 作廢':''}</h3><small>${fmt(r.changed_at)}</small><p>${money(amount(p.counts))} · ${BOXES[p.from]}</p><p>${p.counts.map((n,i)=>n?`$${LABELS[i]} ${i<6?'紙幣':'硬幣'} × ${n}`:'').filter(Boolean).join('、')}</p>${r.reason?`<p>${esc(r.reason)}</p>`:''}</div>`;}).join('')}`,button('revise-cash','修訂','edit','secondary',`data-id="${id}"`)+button('void-cash',e.voided?'恢復交易':'作廢交易','history','danger',`data-id="${id}"`));}
