function importPanel(){showSheet('匯入舊資料',`<p>支援 PersonalOS 網頁備份，以及附帶遷移工具產生嘅 Android 完整匯出 JSON。先預覽再合併；不清空資料。</p><label class="field">選擇 JSON<input type="file" id="import-file" accept=".json,application/json"></label><div id="import-preview"></div>`);$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>25000000)throw Error('檔案過大，請先檢查備份');const incoming=validateState(JSON.parse(await file.text()));mergeBackup(S,incoming);$('#import-preview').innerHTML=`<div class="notice">${incoming.revisions.length} 筆交易修訂<br>${incoming.memos.length} 筆備忘<br>${incoming.cards.length} 筆 SD 卡紀錄<br>庫存總額 ${money(replay(entries(incoming.revisions)).total)}</div><button class="primary" id="import-confirm">先下載目前備份，再合併匯入</button>`;$('#import-confirm').onclick=async ev=>{ev.currentTarget.disabled=true;try{backup();await update(s=>Object.assign(s,mergeBackup(s,incoming)),true);if(incoming.cloudOutbox?.length)localStorage.setItem('pos-imported-outbox-archive-'+Date.now(),JSON.stringify(incoming.cloudOutbox));sheetExit($('#sheet'));render();toast('匯入完成，原修訂歷史保留');}catch(err){sheetError(err);ev.currentTarget.disabled=false;}};}catch(err){sheetError(err);}};}
