document.addEventListener('keydown',e=>{lastActive=Date.now();if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchPanel();}});document.addEventListener('pointerdown',()=>lastActive=Date.now());document.addEventListener('input',()=>lastActive=Date.now());document.addEventListener('scroll',()=>lastActive=Date.now(),{passive:true});
window.addEventListener('hashchange',()=>go(location.hash.slice(1),false));$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};window.addEventListener('storage',e=>{if(e.key===KEY){try{S=overlayDrafts(validateState(JSON.parse(e.newValue)));if(!$('#sheet').open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))render();}catch{toast('另一頁資料更新異常，停止自動重載');}}});
