setInterval(tick,100);setInterval(()=>{if(Number(U.idle)&&!['home','display'].includes(route)&&!document.hidden&&!(route==='memos'&&S.drafts['memo-compose-'+memoScope])&&!$('#sheet').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&Date.now()-lastActive>Number(U.idle)*60000)go('display');},10000);
