setInterval(()=>{if($('#sheet').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;applySettings();const t=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Hong_Kong',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()),day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong'}).format(new Date());if($('#night-reminder')&&t>=U.reminder&&night()&&U.reminded!==day){$('#night-reminder').textContent='☾ 夜深喇，記得休息。';U.reminded=day;saveUI();}},30000);

function bindDockOrder(){
 const rail=$('.living-dock');if(!rail)return;
 const buttons=$$('.dock-button[data-route]',rail);let dragged=null;
 const saveOrder=()=>{U.dockOrder=$$('.dock-button[data-route]',rail).map(b=>b.dataset.route);saveUI();};
 const move=(b,target)=>{const before=new Map($$('.dock-button',rail).map(e=>[e,e.getBoundingClientRect()]));const all=[...rail.children];rail.insertBefore(b,all.indexOf(b)<all.indexOf(target)?target.nextSibling:target);saveOrder();if(document.documentElement.dataset.motion==='on'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)before.forEach((r,e)=>{const n=e.getBoundingClientRect();e.animate([{transform:`translate(${r.x-n.x}px,${r.y-n.y}px)`},{transform:'none'}],{duration:250,easing:'cubic-bezier(.2,.8,.2,1)'});});};
 buttons.forEach(b=>{b.draggable=matchMedia('(pointer:fine)').matches;b.addEventListener('dragstart',e=>{dragged=b;b.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',b.dataset.route);});b.addEventListener('dragover',e=>{if(dragged&&dragged!==b){e.preventDefault();b.classList.add('drop-target');}});b.addEventListener('dragleave',()=>b.classList.remove('drop-target'));b.addEventListener('drop',e=>{e.preventDefault();b.classList.remove('drop-target');if(dragged&&dragged!==b)move(dragged,b);});b.addEventListener('dragend',()=>{buttons.forEach(e=>e.classList.remove('dragging','drop-target'));dragged=null;});});
 const edit=document.createElement('button');edit.className='text-button dock-reorder';edit.textContent='排列常用程式';edit.onclick=()=>{showSheet('排列常用程式',`<p>拖曳適用滑鼠；手機及鍵盤可用以下按鈕。只改此裝置嘅入口次序。</p><div id="dock-order"></div>`);const draw=()=>{$('#dock-order').innerHTML=$$('.dock-button[data-route]',rail).map((b,i,a)=>`<div class="dock-order-actions"><strong>${esc(b.textContent)}</strong><button data-order="${b.dataset.route}" data-dir="-1" ${i===0?'disabled':''}>向前</button><button data-order="${b.dataset.route}" data-dir="1" ${i===a.length-1?'disabled':''}>向後</button></div>`).join('');$$('[data-order]').forEach(b=>b.onclick=()=>{const a=$$('.dock-button[data-route]',rail),el=a.find(e=>e.dataset.route===b.dataset.order),target=a[a.indexOf(el)+Number(b.dataset.dir)];if(target)move(el,target);draw();});};draw();};rail.parentElement.append(edit);
}

function resizeCashViewport(){const v=window.visualViewport;const z=Number(S.settings.font)||1;document.documentElement.style.setProperty('--cash-vh',((v?.height||innerHeight)/z)+'px');document.documentElement.style.setProperty('--cash-top',((v?.offsetTop||0)/z)+'px');}window.visualViewport?.addEventListener('resize',resizeCashViewport);window.visualViewport?.addEventListener('scroll',resizeCashViewport);window.addEventListener('resize',resizeCashViewport);resizeCashViewport();

function updateStorageStatus(){const el=document.querySelector('[data-storage-status]');if(!el)return;let label='已保存於本機 · 未啟用雲端同步';if(localStorage.getItem('pos-web-sync')==='1'){label=localStorage.getItem('pos-web-conflict')?'已保存於本機 · 同步待處理':localStorage.getItem('pos-web-dirty')==='1'?'已保存於本機 · '+(navigator.onLine?'等待同步':'離線待同步'):cloud?.state.web?'雲端版本已讀取 · 本機沒有待送變更':'已保存於本機 · 等待雲端確認';if(cloud?.state.webStatus)label+=' · '+cloud.state.webStatus;}el.textContent=label;}setInterval(updateStorageStatus,1000);
async function setupUpdates(){try{const reg=await navigator.serviceWorker.register('./sw.js');let approved=false;function offer(){if(!reg.waiting||document.querySelector('#pwa-update'))return;const b=document.createElement('button');b.id='pwa-update';b.className='pwa-update';b.textContent='有新版 · 按此更新';b.onclick=async()=>{if(document.querySelector('#sheet')?.open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){toast('請先返回列表；草稿會保留，再按更新。');return;}approved=true;b.disabled=true;b.textContent='正在更新…';reg.waiting.postMessage({type:'ACTIVATE_UPDATE'});};document.body.append(b);}offer();reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)offer();});});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(approved)location.reload();});}catch{toast('離線快取未能啟用，請保持連線');}}
